--[=[
    @class IEventBus
    事件总线接口
]=]

export type IEventBus = {
    --- 触发事件
    Fire: (eventName: string, ...any) -> (),

    --- 触发服务器事件
    FireServer: (eventName: string, ...any) -> (),

    --- 触发指定客户端事件
    FireClient: (player: Player, eventName: string, ...any) -> (),

    --- 触发所有客户端事件
    FireAllClients: (eventName: string, ...any) -> (),

    --- 连接事件处理器
    Connect: (func: (eventName: string, ...any) -> ()) -> RBXScriptConnection,

    --- 连接客户端到服务器事件处理器
    ConnectC2S: (func: (player: Player, eventName: string, ...any) -> ()) -> RBXScriptConnection,

    --- 连接服务器到客户端事件处理器
    ConnectS2C: (func: (eventName: string, ...any) -> ()) -> RBXScriptConnection,

    --- 调用事件并等待返回
    Invoke: (eventName: string, ...any) -> any,

    --- 调用服务器事件并等待返回
    InvokeServer: (eventName: string, ...any) -> any,

    --- 连接调用处理器
    OnInvoke: (func: (eventName: string, ...any) -> ()) -> RBXScriptConnection,

    --- 连接客户端到服务器调用处理器
    OnInvokeC2S: (func: (player: Player, eventName: string, ...any) -> ()) -> RBXScriptConnection
}

return {}